PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kg: <https://moosedev.dev/kg/>
SELECT ?title WHERE {
  ?s a kg:Lesson ; rdfs:label ?title .
}
ORDER BY ?title

